def gpx_fields_to_xml(instance: Any, tag: str, version: str,
    custom_attributes: Dict[str, str]={}, nsmap: Dict[str, str]={},
    prettyprint: bool=True, indent: str='', empty_body: bool=False) ->str:
    if not prettyprint:
        indent = ''
    fields = instance.gpx_10_fields
    if version == '1.1':
        fields = fields + instance.gpx_11_fields

    tag_open = f'\n{indent}<{tag}'
    body = []
    attributes = []

    if custom_attributes:
        for key, value in custom_attributes.items():
            attributes.append(f' {key}="{mod_utils.make_str(value)}"')

    for field in fields:
        if isinstance(field, str):
            continue
        if field.attribute:
            value = getattr(instance, field.name)
            xml_value = field.to_xml(value, version, nsmap, prettyprint=prettyprint, indent=indent)
            if xml_value:
                attributes.append(f' {xml_value}')
        else:
            value = getattr(instance, field.name)
            xml_value = field.to_xml(value, version, nsmap, prettyprint=prettyprint, indent=f'{indent}  ')
            if xml_value:
                body.append(xml_value)

    if not body and not empty_body:
        return f'{tag_open}{"".join(attributes)} />'

    result = [tag_open, ''.join(attributes), '>']
    result.extend(body)
    if prettyprint:
        result.append(f'\n{indent}</{tag}>')
    else:
        result.append(f'</{tag}>')
    return ''.join(result)
